CREATE TABLE IF NOT EXISTS staffing_registers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(64) NOT NULL,name VARCHAR(255) NOT NULL,organizational_structure_id BIGINT UNSIGNED NOT NULL,note TEXT,status VARCHAR(20) NOT NULL DEFAULT 'active',revision INT UNSIGNED NOT NULL DEFAULT 1,created_by BIGINT UNSIGNED,created_at DATETIME NOT NULL,updated_by BIGINT UNSIGNED,updated_at DATETIME NOT NULL,archived_by BIGINT UNSIGNED,archived_at DATETIME,archive_reason VARCHAR(1000),restored_by BIGINT UNSIGNED,restored_at DATETIME,restore_reason VARCHAR(1000),UNIQUE KEY uq_staffing_registers_code(code),UNIQUE KEY uq_staffing_registers_binding(id,organizational_structure_id),FOREIGN KEY(organizational_structure_id) REFERENCES organizational_structures(id),CHECK(status IN('active','archived')),CHECK(revision>0))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS staffing_slot_identities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staffing_register_id BIGINT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED,created_at DATETIME NOT NULL,UNIQUE KEY uq_staffing_slot_identities_binding(id,staffing_register_id),FOREIGN KEY(staffing_register_id) REFERENCES staffing_registers(id))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS staffing_versions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staffing_register_id BIGINT UNSIGNED NOT NULL,based_on_version_id BIGINT UNSIGNED,organizational_structure_id BIGINT UNSIGNED NOT NULL,organizational_structure_version_id BIGINT UNSIGNED NOT NULL,position_catalog_version_id BIGINT UNSIGNED NOT NULL,rank_catalog_version_id BIGINT UNSIGNED NOT NULL,vus_catalog_version_id BIGINT UNSIGNED NOT NULL,version_number INT UNSIGNED NOT NULL,version_label VARCHAR(255) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',effective_from DATE NOT NULL,effective_to DATE,change_reason VARCHAR(1000) NOT NULL,revision INT UNSIGNED NOT NULL DEFAULT 1,pending_guard BIGINT UNSIGNED GENERATED ALWAYS AS(CASE WHEN status IN('draft','approved') THEN staffing_register_id END) STORED,active_guard BIGINT UNSIGNED GENERATED ALWAYS AS(CASE WHEN status='active' THEN staffing_register_id END) STORED,created_by BIGINT UNSIGNED,created_at DATETIME NOT NULL,updated_by BIGINT UNSIGNED,updated_at DATETIME NOT NULL,approved_by BIGINT UNSIGNED,approved_at DATETIME,activated_by BIGINT UNSIGNED,activated_at DATETIME,cancelled_by BIGINT UNSIGNED,cancelled_at DATETIME,cancellation_reason VARCHAR(1000),UNIQUE KEY uq_staffing_versions_number(staffing_register_id,version_number),UNIQUE KEY uq_staffing_versions_id_register(id,staffing_register_id),UNIQUE KEY uq_staffing_versions_binding(id,staffing_register_id,organizational_structure_id,organizational_structure_version_id,position_catalog_version_id,rank_catalog_version_id,vus_catalog_version_id),UNIQUE KEY uq_staffing_versions_pending_guard(pending_guard),UNIQUE KEY uq_staffing_versions_active_guard(active_guard),FOREIGN KEY(staffing_register_id,organizational_structure_id) REFERENCES staffing_registers(id,organizational_structure_id),FOREIGN KEY(based_on_version_id,staffing_register_id) REFERENCES staffing_versions(id,staffing_register_id),FOREIGN KEY(organizational_structure_version_id,organizational_structure_id) REFERENCES organizational_structure_versions(id,organizational_structure_id),FOREIGN KEY(position_catalog_version_id) REFERENCES military_position_catalog_versions(id),FOREIGN KEY(rank_catalog_version_id) REFERENCES military_rank_catalog_versions(id),FOREIGN KEY(vus_catalog_version_id) REFERENCES military_occupational_specialty_catalog_versions(id),CHECK(status IN('draft','approved','active','superseded','cancelled')),CHECK(effective_to IS NULL OR effective_to>effective_from),CHECK(revision>0))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS staffing_documents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staffing_register_id BIGINT UNSIGNED NOT NULL,document_type VARCHAR(32) NOT NULL,document_date DATE NOT NULL,document_number VARCHAR(128) NOT NULL,title VARCHAR(255) NOT NULL,note TEXT,created_by BIGINT UNSIGNED,created_at DATETIME NOT NULL,updated_by BIGINT UNSIGNED,updated_at DATETIME NOT NULL,UNIQUE KEY uq_staffing_documents_binding(id,staffing_register_id),FOREIGN KEY(staffing_register_id) REFERENCES staffing_registers(id),CHECK(document_type IN('staffing_order','amendment_order','approval_act','other_basis')))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS staffing_version_documents(staffing_version_id BIGINT UNSIGNED NOT NULL,staffing_register_id BIGINT UNSIGNED NOT NULL,document_id BIGINT UNSIGNED NOT NULL,document_role VARCHAR(24) NOT NULL,sort_order INT UNSIGNED NOT NULL,primary_guard BIGINT UNSIGNED GENERATED ALWAYS AS(CASE WHEN document_role='primary_basis' THEN staffing_version_id END) STORED,created_by BIGINT UNSIGNED,created_at DATETIME NOT NULL,PRIMARY KEY(staffing_version_id,document_id),UNIQUE KEY uq_staffing_version_documents_order(staffing_version_id,sort_order),UNIQUE KEY uq_staffing_version_documents_primary(primary_guard),FOREIGN KEY(staffing_version_id,staffing_register_id) REFERENCES staffing_versions(id,staffing_register_id),FOREIGN KEY(document_id,staffing_register_id) REFERENCES staffing_documents(id,staffing_register_id),CHECK(document_role IN('primary_basis','additional_basis','amendment')))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS staffing_slots(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staffing_register_id BIGINT UNSIGNED NOT NULL,staffing_version_id BIGINT UNSIGNED NOT NULL,staffing_slot_identity_id BIGINT UNSIGNED NOT NULL,organizational_structure_id BIGINT UNSIGNED NOT NULL,organizational_structure_version_id BIGINT UNSIGNED NOT NULL,organizational_structure_element_id BIGINT UNSIGNED NOT NULL,position_catalog_version_id BIGINT UNSIGNED NOT NULL,position_type_id BIGINT UNSIGNED NOT NULL,position_variant_id BIGINT UNSIGNED,rank_catalog_version_id BIGINT UNSIGNED NOT NULL,vus_catalog_version_id BIGINT UNSIGNED NOT NULL,minimum_rank_id BIGINT UNSIGNED,maximum_rank_id BIGINT UNSIGNED,preferred_rank_id BIGINT UNSIGNED,internal_code VARCHAR(64),display_name VARCHAR(255) NOT NULL,normative_state VARCHAR(20) NOT NULL DEFAULT 'active',note TEXT,sort_order INT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED,created_at DATETIME NOT NULL,updated_by BIGINT UNSIGNED,updated_at DATETIME NOT NULL,UNIQUE KEY uq_staffing_slots_identity(staffing_version_id,staffing_slot_identity_id),UNIQUE KEY uq_staffing_slots_code(staffing_version_id,internal_code),UNIQUE KEY uq_staffing_slots_order(staffing_version_id,organizational_structure_element_id,sort_order),UNIQUE KEY uq_staffing_slots_binding(id,staffing_version_id,staffing_register_id),FOREIGN KEY(staffing_version_id,staffing_register_id,organizational_structure_id,organizational_structure_version_id,position_catalog_version_id,rank_catalog_version_id,vus_catalog_version_id) REFERENCES staffing_versions(id,staffing_register_id,organizational_structure_id,organizational_structure_version_id,position_catalog_version_id,rank_catalog_version_id,vus_catalog_version_id),FOREIGN KEY(staffing_slot_identity_id,staffing_register_id) REFERENCES staffing_slot_identities(id,staffing_register_id),FOREIGN KEY(organizational_structure_version_id,organizational_structure_element_id) REFERENCES organizational_structure_nodes(structure_version_id,organizational_structure_element_id),FOREIGN KEY(position_type_id) REFERENCES military_position_types(id),FOREIGN KEY(position_variant_id) REFERENCES military_position_variants(id),FOREIGN KEY(minimum_rank_id) REFERENCES military_rank_levels(id),FOREIGN KEY(maximum_rank_id) REFERENCES military_rank_levels(id),FOREIGN KEY(preferred_rank_id) REFERENCES military_rank_levels(id),CHECK(normative_state IN('active','suspended','closed')),CHECK(sort_order>0))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS staffing_slot_vus_requirements(staffing_version_id BIGINT UNSIGNED NOT NULL,staffing_register_id BIGINT UNSIGNED NOT NULL,staffing_slot_id BIGINT UNSIGNED NOT NULL,vus_catalog_version_id BIGINT UNSIGNED NOT NULL,public_disclosure_id BIGINT UNSIGNED NOT NULL,requirement_role VARCHAR(20) NOT NULL,sort_order INT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED,created_at DATETIME NOT NULL,PRIMARY KEY(staffing_slot_id,public_disclosure_id),UNIQUE KEY uq_staffing_slot_vus_order(staffing_slot_id,sort_order),FOREIGN KEY(staffing_slot_id,staffing_version_id,staffing_register_id) REFERENCES staffing_slots(id,staffing_version_id,staffing_register_id),FOREIGN KEY(vus_catalog_version_id) REFERENCES military_occupational_specialty_catalog_versions(id),FOREIGN KEY(public_disclosure_id) REFERENCES military_occupational_specialty_public_disclosures(id),CHECK(requirement_role IN('required','allowed','preferred')))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS staffing_change_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,staffing_register_id BIGINT UNSIGNED NOT NULL,staffing_version_id BIGINT UNSIGNED,staffing_slot_identity_id BIGINT UNSIGNED,actor_user_id BIGINT UNSIGNED,event_type VARCHAR(80) NOT NULL,target_type VARCHAR(32) NOT NULL,target_id BIGINT UNSIGNED,before_state JSON,after_state JSON,reason VARCHAR(1000),created_at DATETIME NOT NULL,KEY idx_staffing_change_events(staffing_register_id,created_at,id),FOREIGN KEY(staffing_register_id) REFERENCES staffing_registers(id),FOREIGN KEY(staffing_version_id,staffing_register_id) REFERENCES staffing_versions(id,staffing_register_id),FOREIGN KEY(staffing_slot_identity_id,staffing_register_id) REFERENCES staffing_slot_identities(id,staffing_register_id))ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TRIGGER IF EXISTS trg_staffing_versions_insert;CREATE TRIGGER trg_staffing_versions_insert BEFORE INSERT ON staffing_versions FOR EACH ROW BEGIN IF NOT EXISTS(SELECT 1 FROM organizational_structure_versions o JOIN military_position_catalog_versions p ON p.id=NEW.position_catalog_version_id JOIN military_occupational_specialty_catalog_versions v ON v.id=NEW.vus_catalog_version_id WHERE o.id=NEW.organizational_structure_version_id AND o.organizational_structure_id=NEW.organizational_structure_id AND o.status IN('active','superseded') AND p.status='published' AND p.rank_catalog_version_id=NEW.rank_catalog_version_id AND v.status='published') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_VERSION_CATALOG_INVALID';END IF;IF NEW.based_on_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM staffing_versions b WHERE b.id=NEW.based_on_version_id AND b.staffing_register_id=NEW.staffing_register_id AND b.status='active' AND b.organizational_structure_version_id=NEW.organizational_structure_version_id AND b.position_catalog_version_id=NEW.position_catalog_version_id AND b.rank_catalog_version_id=NEW.rank_catalog_version_id AND b.vus_catalog_version_id=NEW.vus_catalog_version_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_BASE_VERSION_INVALID';END IF;END;
DROP TRIGGER IF EXISTS trg_staffing_versions_update;CREATE TRIGGER trg_staffing_versions_update BEFORE UPDATE ON staffing_versions FOR EACH ROW BEGIN IF NOT(NEW.staffing_register_id<=>OLD.staffing_register_id) OR NOT(NEW.based_on_version_id<=>OLD.based_on_version_id) OR NOT(NEW.organizational_structure_id<=>OLD.organizational_structure_id) OR NOT(NEW.organizational_structure_version_id<=>OLD.organizational_structure_version_id) OR NOT(NEW.position_catalog_version_id<=>OLD.position_catalog_version_id) OR NOT(NEW.rank_catalog_version_id<=>OLD.rank_catalog_version_id) OR NOT(NEW.vus_catalog_version_id<=>OLD.vus_catalog_version_id) OR NOT(NEW.version_number<=>OLD.version_number) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_VERSION_BINDING_IMMUTABLE';END IF;IF(OLD.status='draft' AND NEW.status NOT IN('draft','approved','cancelled')) OR(OLD.status='approved' AND NEW.status NOT IN('approved','active','cancelled')) OR(OLD.status='active' AND NEW.status NOT IN('active','superseded')) OR OLD.status IN('superseded','cancelled') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_VERSION_TRANSITION_INVALID';END IF;IF OLD.status<>'draft' AND (NOT(NEW.version_label<=>OLD.version_label) OR NOT(NEW.effective_from<=>OLD.effective_from) OR NOT(NEW.change_reason<=>OLD.change_reason) OR NOT(NEW.revision<=>OLD.revision)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_PUBLISHED_VERSION_CONTENT_IMMUTABLE';END IF;END;
DROP TRIGGER IF EXISTS trg_staffing_versions_delete;CREATE TRIGGER trg_staffing_versions_delete BEFORE DELETE ON staffing_versions FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_VERSION_DELETE_FORBIDDEN';END;
DROP TRIGGER IF EXISTS trg_staffing_documents_update;CREATE TRIGGER trg_staffing_documents_update BEFORE UPDATE ON staffing_documents FOR EACH ROW BEGIN IF EXISTS(SELECT 1 FROM staffing_version_documents d JOIN staffing_versions v ON v.id=d.staffing_version_id WHERE d.document_id=OLD.id AND v.status<>'draft') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_PUBLISHED_DOCUMENT_IMMUTABLE';END IF;END;
DROP TRIGGER IF EXISTS trg_staffing_version_documents_insert;CREATE TRIGGER trg_staffing_version_documents_insert BEFORE INSERT ON staffing_version_documents FOR EACH ROW BEGIN IF(SELECT status FROM staffing_versions WHERE id=NEW.staffing_version_id)<>'draft' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_VERSION_DOCUMENT_DRAFT_ONLY';END IF;END;
DROP TRIGGER IF EXISTS trg_staffing_version_documents_change;CREATE TRIGGER trg_staffing_version_documents_change BEFORE UPDATE ON staffing_version_documents FOR EACH ROW BEGIN IF(SELECT status FROM staffing_versions WHERE id=OLD.staffing_version_id)<>'draft' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_VERSION_DOCUMENT_DRAFT_ONLY';END IF;IF NOT(NEW.staffing_version_id<=>OLD.staffing_version_id) OR NOT(NEW.staffing_register_id<=>OLD.staffing_register_id) OR NOT(NEW.document_id<=>OLD.document_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_VERSION_DOCUMENT_LINK_IDENTITY_IMMUTABLE';END IF;END;
DROP TRIGGER IF EXISTS trg_staffing_version_documents_delete;CREATE TRIGGER trg_staffing_version_documents_delete BEFORE DELETE ON staffing_version_documents FOR EACH ROW BEGIN IF(SELECT status FROM staffing_versions WHERE id=OLD.staffing_version_id)<>'draft' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_VERSION_DOCUMENT_DRAFT_ONLY';END IF;END;
DROP TRIGGER IF EXISTS trg_staffing_slots_insert;CREATE TRIGGER trg_staffing_slots_insert BEFORE INSERT ON staffing_slots FOR EACH ROW BEGIN IF(SELECT status FROM staffing_versions WHERE id=NEW.staffing_version_id)<>'draft' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_SLOT_INSERT_DRAFT_ONLY';END IF;IF NOT EXISTS(SELECT 1 FROM military_position_types t WHERE t.id=NEW.position_type_id AND t.catalog_version_id=NEW.position_catalog_version_id) OR(NEW.position_variant_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM military_position_variants v WHERE v.id=NEW.position_variant_id AND v.catalog_version_id=NEW.position_catalog_version_id AND v.position_type_id=NEW.position_type_id)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_SLOT_POSITION_INVALID';END IF;IF(NEW.minimum_rank_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM military_rank_levels r WHERE r.id=NEW.minimum_rank_id AND r.catalog_version_id=NEW.rank_catalog_version_id)) OR(NEW.maximum_rank_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM military_rank_levels r WHERE r.id=NEW.maximum_rank_id AND r.catalog_version_id=NEW.rank_catalog_version_id)) OR(NEW.preferred_rank_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM military_rank_levels r WHERE r.id=NEW.preferred_rank_id AND r.catalog_version_id=NEW.rank_catalog_version_id)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_SLOT_RANK_INVALID';END IF;END;
DROP TRIGGER IF EXISTS trg_staffing_slots_update;CREATE TRIGGER trg_staffing_slots_update BEFORE UPDATE ON staffing_slots FOR EACH ROW BEGIN IF(SELECT status FROM staffing_versions WHERE id=OLD.staffing_version_id)<>'draft' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_SLOT_UPDATE_DRAFT_ONLY';END IF;IF NOT(NEW.staffing_register_id<=>OLD.staffing_register_id) OR NOT(NEW.staffing_version_id<=>OLD.staffing_version_id) OR NOT(NEW.staffing_slot_identity_id<=>OLD.staffing_slot_identity_id) OR NOT(NEW.organizational_structure_id<=>OLD.organizational_structure_id) OR NOT(NEW.organizational_structure_version_id<=>OLD.organizational_structure_version_id) OR NOT(NEW.position_catalog_version_id<=>OLD.position_catalog_version_id) OR NOT(NEW.rank_catalog_version_id<=>OLD.rank_catalog_version_id) OR NOT(NEW.vus_catalog_version_id<=>OLD.vus_catalog_version_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_SLOT_IDENTITY_IMMUTABLE';END IF;IF NOT EXISTS(SELECT 1 FROM military_position_types t WHERE t.id=NEW.position_type_id AND t.catalog_version_id=NEW.position_catalog_version_id) OR(NEW.position_variant_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM military_position_variants v WHERE v.id=NEW.position_variant_id AND v.catalog_version_id=NEW.position_catalog_version_id AND v.position_type_id=NEW.position_type_id)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_SLOT_POSITION_INVALID';END IF;IF(NEW.minimum_rank_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM military_rank_levels r WHERE r.id=NEW.minimum_rank_id AND r.catalog_version_id=NEW.rank_catalog_version_id)) OR(NEW.maximum_rank_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM military_rank_levels r WHERE r.id=NEW.maximum_rank_id AND r.catalog_version_id=NEW.rank_catalog_version_id)) OR(NEW.preferred_rank_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM military_rank_levels r WHERE r.id=NEW.preferred_rank_id AND r.catalog_version_id=NEW.rank_catalog_version_id)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_SLOT_RANK_INVALID';END IF;END;
DROP TRIGGER IF EXISTS trg_staffing_slots_delete;CREATE TRIGGER trg_staffing_slots_delete BEFORE DELETE ON staffing_slots FOR EACH ROW BEGIN IF(SELECT status FROM staffing_versions WHERE id=OLD.staffing_version_id)<>'draft' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_SLOT_DELETE_DRAFT_ONLY';END IF;END;
DROP TRIGGER IF EXISTS trg_staffing_slot_vus_insert;CREATE TRIGGER trg_staffing_slot_vus_insert BEFORE INSERT ON staffing_slot_vus_requirements FOR EACH ROW BEGIN IF NOT EXISTS(SELECT 1 FROM staffing_slots s JOIN staffing_versions v ON v.id=s.staffing_version_id JOIN military_occupational_specialty_public_disclosures d ON d.id=NEW.public_disclosure_id WHERE s.id=NEW.staffing_slot_id AND s.staffing_version_id=NEW.staffing_version_id AND s.staffing_register_id=NEW.staffing_register_id AND s.vus_catalog_version_id=NEW.vus_catalog_version_id AND v.status='draft' AND d.catalog_version_id=NEW.vus_catalog_version_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_SLOT_VUS_INVALID';END IF;END;
DROP TRIGGER IF EXISTS trg_staffing_slot_vus_update;CREATE TRIGGER trg_staffing_slot_vus_update BEFORE UPDATE ON staffing_slot_vus_requirements FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_SLOT_VUS_UPDATE_FORBIDDEN';END;
DROP TRIGGER IF EXISTS trg_staffing_slot_vus_delete;CREATE TRIGGER trg_staffing_slot_vus_delete BEFORE DELETE ON staffing_slot_vus_requirements FOR EACH ROW BEGIN IF(SELECT status FROM staffing_versions WHERE id=OLD.staffing_version_id)<>'draft' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_SLOT_VUS_DELETE_DRAFT_ONLY';END IF;END;
DROP TRIGGER IF EXISTS trg_staffing_events_update;CREATE TRIGGER trg_staffing_events_update BEFORE UPDATE ON staffing_change_events FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_EVENT_APPEND_ONLY';END;
DROP TRIGGER IF EXISTS trg_staffing_events_delete;CREATE TRIGGER trg_staffing_events_delete BEFORE DELETE ON staffing_change_events FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='STAFFING_EVENT_APPEND_ONLY';END;
INSERT INTO permissions(code,name,description,is_system,created_at,updated_at)SELECT 'staffing.registers.view','Просмотр штатной структуры','Просмотр штатных реестров и версий.',TRUE,NOW(),NOW()WHERE NOT EXISTS(SELECT 1 FROM permissions WHERE code='staffing.registers.view');
INSERT INTO permissions(code,name,description,is_system,created_at,updated_at)SELECT 'staffing.registers.create','Создание штатных реестров','Создание реестров и версий.',TRUE,NOW(),NOW()WHERE NOT EXISTS(SELECT 1 FROM permissions WHERE code='staffing.registers.create');
INSERT INTO permissions(code,name,description,is_system,created_at,updated_at)SELECT 'staffing.registers.update','Изменение штатной структуры','Изменение черновых версий.',TRUE,NOW(),NOW()WHERE NOT EXISTS(SELECT 1 FROM permissions WHERE code='staffing.registers.update');
INSERT INTO permissions(code,name,description,is_system,created_at,updated_at)SELECT 'staffing.registers.publish','Публикация штатной структуры','Утверждение и активация версий.',TRUE,NOW(),NOW()WHERE NOT EXISTS(SELECT 1 FROM permissions WHERE code='staffing.registers.publish');
INSERT INTO permissions(code,name,description,is_system,created_at,updated_at)SELECT 'staffing.registers.archive','Архивирование штатных реестров','Архивирование и восстановление.',TRUE,NOW(),NOW()WHERE NOT EXISTS(SELECT 1 FROM permissions WHERE code='staffing.registers.archive');
INSERT INTO permissions(code,name,description,is_system,created_at,updated_at)SELECT 'staffing.registers.history','История штатной структуры','Просмотр предметной истории.',TRUE,NOW(),NOW()WHERE NOT EXISTS(SELECT 1 FROM permissions WHERE code='staffing.registers.history');
